/*
 * Stub trace header for QCOM clk debug driver.
 *
 * This header is normally generated by the Android build system from
 * tracepoint definitions. This standalone kernel tree provides a minimal
 * stub so the driver compiles without the Android-specific trace
 * infrastructure.
 */

#ifndef __TRACE_CLOCK_QCOM_H
#define __TRACE_CLOCK_QCOM_H

static inline void trace_clk_measure(const char *name, unsigned long val)
{
}

static inline void trace_clk_state(const char *name,
                                   unsigned int prepared,
                                   unsigned int enabled,
                                   unsigned long rate,
                                   unsigned int vdd_level)
{
}

#endif /* __TRACE_CLOCK_QCOM_H */
